      en: ["Surface area of approximately 1,088 square kilometers", "Second largest lake within the Los Glaciares National Park", "Fed by the Viedma Glacier, Argentina's largest outlet glacier", "Approximately 80 kilometers long and 15 kilometers wide", "Discovered in 1782 by Spanish explorer Antonio de Viedma", "Maximum depth is estimated to exceed 300 meters", "Connected to Lake Argentino by the La Leona River", "Known for its large drifting icebergs from the Viedma Glacier"],
