      es: ["Ubicación del faro del fin del mundo", "Reserva natural con pingüinos y focas", "Conocida por las tormentas"],
      pt: ["Localização do Farol do Fim do Mundo", "Reserva natural com pinguins e focas", "Conhecida por tempestades"],
